package eit_acquisition_supervisor.EIT_Acquisition_Supervisor

import org.sireum._
import art.Art
import eit_acquisition_supervisor._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait FaultComposition_acquisition_process_fault_composition_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_fault_composition)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_fault_composition)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_fault_composition)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_fault_composition)
  }

  /** helper function to set the values of all input ports.
   * @param request_facts payload for data port request_facts
   * @param preparation_facts payload for data port preparation_facts
   * @param equipment_facts payload for data port equipment_facts
   * @param batch_facts payload for data port batch_facts
   * @param image_result_facts payload for data port image_result_facts
   */
  def put_concrete_inputs(request_facts : EIT_Acquisition_Supervisor.RequestFactsRecord,
                          preparation_facts : EIT_Acquisition_Supervisor.PreparationFacts.Type,
                          equipment_facts : EIT_Acquisition_Supervisor.EquipmentFacts.Type,
                          batch_facts : EIT_Acquisition_Supervisor.BatchFacts.Type,
                          image_result_facts : EIT_Acquisition_Supervisor.ImageResultFacts.Type): Unit = {
    put_request_facts(request_facts)
    put_preparation_facts(preparation_facts)
    put_equipment_facts(equipment_facts)
    put_batch_facts(batch_facts)
    put_image_result_facts(image_result_facts)
  }


  /** helper function to check FaultComposition_acquisition_process_fault_composition's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param fault_summary method that will be called with the value of the outgoing data
   *        port 'fault_summary'.
   */
  def check_concrete_output(fault_summary: EIT_Acquisition_Supervisor.FaultSummary => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val fault_summaryValue: EIT_Acquisition_Supervisor.FaultSummary = get_fault_summary().get
    if(!fault_summary(fault_summaryValue)) {
      testFailures = testFailures :+ st"'fault_summary' did not match expected: value of the outgoing data port is ${fault_summaryValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_request_facts(value : EIT_Acquisition_Supervisor.RequestFactsRecord): Unit = {
    Art.insertInInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_fault_composition.operational_api.request_facts_Id, EIT_Acquisition_Supervisor.RequestFactsRecord_Payload(value))
  }

  // setter for in DataPort
  def put_preparation_facts(value : EIT_Acquisition_Supervisor.PreparationFacts.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_fault_composition.operational_api.preparation_facts_Id, EIT_Acquisition_Supervisor.PreparationFacts_Payload(value))
  }

  // setter for in DataPort
  def put_equipment_facts(value : EIT_Acquisition_Supervisor.EquipmentFacts.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_fault_composition.operational_api.equipment_facts_Id, EIT_Acquisition_Supervisor.EquipmentFacts_Payload(value))
  }

  // setter for in DataPort
  def put_batch_facts(value : EIT_Acquisition_Supervisor.BatchFacts.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_fault_composition.operational_api.batch_facts_Id, EIT_Acquisition_Supervisor.BatchFacts_Payload(value))
  }

  // setter for in DataPort
  def put_image_result_facts(value : EIT_Acquisition_Supervisor.ImageResultFacts.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_fault_composition.operational_api.image_result_facts_Id, EIT_Acquisition_Supervisor.ImageResultFacts_Payload(value))
  }

  // getter for out DataPort
  def get_fault_summary(): Option[EIT_Acquisition_Supervisor.FaultSummary] = {
    val value: Option[EIT_Acquisition_Supervisor.FaultSummary] = get_fault_summary_payload() match {
      case Some(EIT_Acquisition_Supervisor.FaultSummary_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port fault_summary.  Expecting 'EIT_Acquisition_Supervisor.FaultSummary_Payload' but received ${v}")
      case _ => None[EIT_Acquisition_Supervisor.FaultSummary]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_fault_summary_payload(): Option[EIT_Acquisition_Supervisor.FaultSummary_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_fault_composition.initialization_api.fault_summary_Id).asInstanceOf[Option[EIT_Acquisition_Supervisor.FaultSummary_Payload]]
  }

}
